class Solution {
public:
    int collectTheCoins(std::vector<int>& coins, std::vector<std::vector<int>>& edges) {
        int n = coins.size();
        std::vector<std::unordered_set<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].insert(e[1]);
            adj[e[1]].insert(e[0]);
        }
        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (adj[i].size() == 1 && coins[i] == 0) {
                q.push(i);
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (adj[u].empty()) continue;
            int v = *adj[u].begin();
            adj[u].erase(v);
            adj[v].erase(u);
            if (adj[v].size() == 1 && coins[v] == 0) {
                q.push(v);
            }
        }
        for (int step = 0; step < 2; ++step) {
            std::vector<int> leaves;
            for (int i = 0; i < n; ++i) {
                if (adj[i].size() == 1) leaves.push_back(i);
            }
            for (int u : leaves) {
                if (!adj[u].empty()) {
                    int v = *adj[u].begin();
                    adj[u].erase(v);
                    adj[v].erase(u);
                }
            }
        }
        int remaining = 0;
        for (int i = 0; i < n; ++i) remaining += adj[i].size();
        return remaining;
    }
};

class Solution {
    public int collectTheCoins(int[] coins, int[][] edges) {
        int n = coins.length;
        java.util.Set<Integer>[] adj = new java.util.HashSet[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.HashSet<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (adj[i].size() == 1 && coins[i] == 0) {
                q.offer(i);
            }
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            if (adj[u].isEmpty()) continue;
            int v = adj[u].iterator().next();
            adj[u].remove(v);
            adj[v].remove(u);
            if (adj[v].size() == 1 && coins[v] == 0) {
                q.offer(v);
            }
        }
        for (int step = 0; step < 2; step++) {
            java.util.List<Integer> leaves = new java.util.ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (adj[i].size() == 1) leaves.add(i);
            }
            for (int u : leaves) {
                if (!adj[u].isEmpty()) {
                    int v = adj[u].iterator().next();
                    adj[u].remove(v);
                    adj[v].remove(u);
                }
            }
        }
        int remaining = 0;
        for (int i = 0; i < n; i++) remaining += adj[i].size();
        return remaining;
    }
}

var collectTheCoins = function(coins, edges) {
    const n = coins.length;
    const adj = Array.from({ length: n }, () => new Set());
    for (const [u, v] of edges) {
        adj[u].add(v);
        adj[v].add(u);
    }
    const q = [];
    for (let i = 0; i < n; i++) {
        if (adj[i].size === 1 && coins[i] === 0) {
            q.push(i);
        }
    }
    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        if (adj[u].size === 0) continue;
        const v = adj[u].values().next().value;
        adj[u].delete(v);
        adj[v].delete(u);
        if (adj[v].size === 1 && coins[v] === 0) {
            q.push(v);
        }
    }
    for (let step = 0; step < 2; step++) {
        const leaves = [];
        for (let i = 0; i < n; i++) {
            if (adj[i].size === 1) leaves.push(i);
        }
        for (const u of leaves) {
            if (adj[u].size > 0) {
                const v = adj[u].values().next().value;
                adj[u].delete(v);
                adj[v].delete(u);
            }
        }
    }
    let remaining = 0;
    for (let i = 0; i < n; i++) remaining += adj[i].size;
    return remaining;
};
